57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /**
66	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
67	     * new owner's id, its assigned {@code customerCode}, its {@code registrationDate} and its
68	     * numeric {@code membershipLevel}.
69	     */
70	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
121	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
122	        if (registrationDate == null) {
123	            registrationDate = java.time.LocalDate.now();
124	        }
125	        registrationDate = toBusinessDay(registrationDate);
126	        owner.setRegistrationDate(registrationDate);
127	        rejectDailyLimitReached(registrationDate);
128	        rejectCityAtCapacity(owner.getCity());
129	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
130	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
131	        }
132	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
133	        rejectDuplicateTelephone(telephone);
134	        owner.setTelephone(telephone);
135	        String email = normalizeEmail(ownerFieldsDto.getEmail());
136	        rejectDuplicateEmail(email);
137	        owner.setEmail(email);
138	        owner.setCustomerCode(assignCustomerCode(owner.getCity(), owner.getLastName()));
139	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
140	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
141	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
142	        this.clinicService.saveOwner(owner);
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
145	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
146	            ownerDto.getMembershipLevel());
147	        headers.setLocation(UriComponentsBuilder.newInstance()
148	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
149	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
150	    }
151	
152	    /**
153	     * The maximum number of owners that may be created in a single day. Creating an owner once this
154	     * many owners already carry today's {@code registrationDate} is rejected.
155	     */
156	    private static final int DAILY_OWNER_LIMIT = 100;
157	
158	    /**
159	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
160	     * given business day as their {@code registrationDate}. The count is keyed by the
161	     * business-day-adjusted registration date of the owner being created (see
162	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
163	     * with no {@code registrationDate} are ignored.
164	     *
165	     * @param registrationDate the business-day-adjusted registration date of the owner being created
166	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
167	     */
168	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
169	        long count = this.clinicService.findAllOwners().stream()
170	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
171	            .count();
172	        if (count >= DAILY_OWNER_LIMIT) {
173	            throw new DailyOwnerLimitException(registrationDate);
174	        }
175	    }
176	
177	    /**
178	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
179	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
180	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
181	     */
182	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
183	
184	    /**
185	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
186	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
187	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
188	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
189	     * owner being created is excluded (it has not yet been saved).
190	     *
191	     * @param registrationDate the business-day-adjusted registration date of the owner being created
192	     * @return {@code true} if more than the threshold of owners already carry this business day
193	     */
194	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
195	        long count = this.clinicService.findAllOwners().stream()
196	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
197	            .count();
198	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
199	    }
200	
201	    /**
202	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is moved forward to
203	     * the following Monday; a weekday is returned unchanged. This applies to the effective
204	     * registration date whether it was supplied in the request or defaulted to the server date, and
205	     * every value derived from the registration date uses the adjusted result.
206	     *
207	     * @param date the effective registration date
208	     * @return {@code date} itself when it is a weekday, otherwise the following Monday
209	     */
210	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
211	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
212	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
213	            date = date.plusDays(1);
214	        }
215	        return date;
216	    }
217	
218	    /**
219	     * The maximum number of owners a single city may contain. Creating an owner in a city that
220	     * already holds this many owners is rejected.
221	     */
222	    private static final int CITY_CAPACITY = 50;
223	
224	    /**
225	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
226	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
227	     * treated as empty), the same way {@link #assignCustomerCode} counts a city's owners.
228	     *
229	     * @param city the city of the owner being created
230	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
231	     */
232	    private void rejectCityAtCapacity(String city) {
233	        String cityValue = city == null ? "" : city;
234	        long count = this.clinicService.findAllOwners().stream()
235	            .filter(existing -> cityValue.equalsIgnoreCase(
236	                existing.getCity() == null ? "" : existing.getCity()))
237	            .count();
238	        if (count >= CITY_CAPACITY) {
239	            throw new CityAtCapacityException(city);
240	        }
241	    }
242	
243	    /**
244	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
245	     * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first
246	     * three letters of the last name and NNNN a per-city 4-digit zero-padded sequence equal to one
247	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
248	     *
249	     * @param city the owner's city
250	     * @param lastName the owner's last name
251	     * @return the assigned customer code
252	     */
253	    private String assignCustomerCode(String city, String lastName) {
254	        String city3 = prefix3(city);
255	        String last3 = prefix3(lastName);
256	        String cityValue = city == null ? "" : city;
257	        int sequence = (int) this.clinicService.findAllOwners().stream()
258	            .filter(existing -> cityValue.equalsIgnoreCase(
259	                existing.getCity() == null ? "" : existing.getCity()))
260	            .count() + 1;
261	        return String.format("%s-%s-%04d", city3, last3, sequence);
262	    }
263	
264	    /**
265	     * Returns the upper-cased first three letters of the given value, or fewer if the value is
266	     * shorter, treating {@code null} as empty.
267	     */
268	    private String prefix3(String value) {
269	        String name = value == null ? "" : value;
270	        return name.substring(0, Math.min(3, name.length()))
271	            .toUpperCase(java.util.Locale.ROOT);
272	    }
273	
274	    /**
275	     * Counts how many existing owners share the given first and last name, compared
276	     * case-insensitively, at the time this owner is created. The value excludes the owner
277	     * being created (which has not yet been saved) and is stored on the new owner and returned
278	     * as its {@code namesakeCount}.
279	     *
280	     * @param firstName the first name of the owner being created
281	     * @param lastName the last name of the owner being created
282	     * @return the number of existing owners with the same first and last name
283	     */
284	    private int countNamesakes(String firstName, String lastName) {
285	        String first = firstName == null ? "" : firstName;
286	        String last = lastName == null ? "" : lastName;
287	        return (int) this.clinicService.findAllOwners().stream()
288	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
289	                && last.equalsIgnoreCase(existing.getLastName()))
290	            .count();
291	    }
292	
293	    /**
294	     * Counts how many existing owners belong to the same household as the owner being created, i.e.
295	     * share its {@code householdId} (derived by {@link Households#householdId} from the normalized last
296	     * name and address). The value excludes the owner being created (which has not yet been saved), so
297	     * the household's size after this create is this count plus one. It is stored on the new owner.
298	     *
299	     * @param lastName the last name of the owner being created
300	     * @param address the normalized address of the owner being created
301	     * @return the number of existing owners sharing this owner's household
302	     */
303	    private int countHouseholdMembers(String lastName, String address) {
304	        String householdId = Households.householdId(lastName, address);
305	        return (int) this.clinicService.findAllOwners().stream()
306	            .filter(existing -> householdId.equals(
307	                Households.householdId(existing.getLastName(), existing.getAddress())))
308	            .count();
309	    }
310	
311	    /**
312	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
313	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
314	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
315	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
316	     * {@code "+61412345678"}. The E.164 value is stored and returned.
317	     * <p>
318	     * The national-number length (the digits after the country code) is additionally validated for
319	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
320	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
321	     *
322	     * @param telephone the raw telephone as submitted
323	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
324	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
325	     *         or its national-number length is wrong for its country code
326	     */
327	    private String normalizeTelephone(String telephone) {
328	        String raw = telephone == null ? "" : telephone.trim();
329	        boolean hasCountryCode = raw.startsWith("+");
330	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
331	        if (hasCountryCode) {
332	            cleaned = cleaned.substring(1);
333	        }
334	        String digits;
335	        if (hasCountryCode) {
336	            digits = cleaned;
337	        } else {
338	            if (cleaned.startsWith("0")) {
339	                cleaned = cleaned.substring(1);
340	            }
341	            digits = "61" + cleaned;
342	        }
343	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
344	            throw new InvalidTelephoneException(telephone);
345	        }
346	        return "+" + digits;
347	    }
348	
349	    /**
350	     * Checks the national-number length of an E.164 digit string against its country code for the
351	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
352	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
353	     *
354	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
355	     * @return {@code true} if the national-number length is acceptable for the country code
356	     */
357	    private boolean hasValidNationalLength(String digits) {
358	        if (digits.startsWith("61")) {
359	            return digits.length() - 2 == 9;
360	        }
361	        if (digits.startsWith("1")) {
362	            return digits.length() - 1 == 10;
363	        }
364	        return true;
365	    }
366	
367	    /**
368	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
369	     * multi-character top-level label. Deliberately lenient about the exact character set while still
370	     * rejecting values that are clearly not addresses (e.g. missing '@').
371	     */
372	    private static final java.util.regex.Pattern EMAIL_PATTERN =
373	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
374	
375	    /**
376	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
377	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
378	     * lower-cased before being stored and returned.
379	     *
380	     * @param email the raw email as submitted, may be {@code null}
381	     * @return the lower-cased email, or {@code null} when none was supplied
382	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
383	     */
384	    private String normalizeEmail(String email) {
385	        if (email == null || email.isBlank()) {
386	            return null;
387	        }
388	        String trimmed = email.trim();
389	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
390	            throw new InvalidEmailException(email);
391	        }
392	        return trimmed.toLowerCase(java.util.Locale.ROOT);
393	    }
394	
395	    /**
396	     * Common street-type abbreviations expanded to their full word during address normalization.
397	     */
398	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
399	        "ST", "STREET",
400	        "RD", "ROAD",
401	        "AVE", "AVENUE");
402	
403	    /**
404	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
405	     * whitespace collapse to a single space, the value is upper-cased and common street-type
406	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
407	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
408	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
409	     * for every address comparison (household duplicate detection and the shared household id).
410	     *
411	     * @param address the raw address as submitted
412	     * @return the normalized address
413	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
414	     */
415	    private String normalizeAddress(String address) {
416	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
417	        if (collapsed.isEmpty()) {
418	            throw new InvalidAddressException(address);
419	        }
420	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
421	        StringBuilder normalized = new StringBuilder(collapsed.length());
422	        for (int i = 0; i < tokens.length; i++) {
423	            if (i > 0) {
424	                normalized.append(' ');
425	            }
426	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
427	        }
428	        return normalized.toString();
429	    }
430	
431	    /**
432	     * Rejects creating an owner whose E.164 telephone is already used by another owner. Telephones of
433	     * existing owners are normalized to E.164 the same way before comparison, so equivalent numbers
434	     * submitted in different formats (e.g. national {@code "0412 345 678"} and international
435	     * {@code "+61 412 345 678"}) are still treated as duplicates.
436	     *
437	     * @param telephone the E.164 telephone of the owner being created
438	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
439	     */
440	    private void rejectDuplicateTelephone(String telephone) {
441	        boolean duplicate = this.clinicService.findAllOwners().stream()
442	            .map(Owner::getTelephone)
443	            .filter(existing -> existing != null)
444	            .map(this::toE164OrNull)
445	            .filter(existing -> existing != null)
446	            .anyMatch(telephone::equals);
447	        if (duplicate) {
448	            throw new DuplicateTelephoneException(telephone);
449	        }
450	    }
451	
452	    /**
453	     * Rejects creating an owner whose email is already used by another owner. Emails are compared by
454	     * their lower-cased form (the same form every owner's email is stored in, see
455	     * {@link #normalizeEmail}), so addresses differing only in letter case still count as duplicates.
456	     * Owners without an email are ignored, and an owner being created without an email is never
457	     * rejected.
458	     *
459	     * @param email the lower-cased email of the owner being created, may be {@code null}
460	     * @throws DuplicateEmailException (409 Conflict) if another owner already uses this email
461	     */
462	    private void rejectDuplicateEmail(String email) {
463	        if (email == null) {
464	            return;
465	        }
466	        boolean duplicate = this.clinicService.findAllOwners().stream()
467	            .map(Owner::getEmail)
468	            .filter(existing -> existing != null)
469	            .map(existing -> existing.toLowerCase(java.util.Locale.ROOT))
470	            .anyMatch(email::equals);
471	        if (duplicate) {
472	            throw new DuplicateEmailException(email);
473	        }
474	    }
475	
476	    /**
477	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
478	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
479	     * when its national-number length does not match its country code.
480	     */
481	    private String toE164OrNull(String telephone) {
482	        try {
483	            return normalizeTelephone(telephone);
484	        } catch (InvalidTelephoneException e) {
485	            return null;
486	        }
487	    }
488	
489	    /**
490	     * Rejects creating an owner who shares a household with an existing owner, i.e. another owner
491	     * already has the same last name and the same address. Last names are compared case-insensitively
492	     * with whitespace collapsed; addresses are compared in their normalized form (see
493	     * {@link #normalizeAddress}, which every owner's stored address already uses), so values that
494	     * differ only in letter case, spacing or a common street-type abbreviation still count as a match.
495	     * This check is skipped when the request sets {@code sharesHousehold} to {@code true}.
496	     *
497	     * @param lastName the last name of the owner being created
498	     * @param address the normalized address of the owner being created
499	     * @throws DuplicateHouseholdException (409 Conflict) if another owner shares this household
500	     */
501	    private void rejectDuplicateHousehold(String lastName, String address) {
502	        String normalizedLastName = Households.normalize(lastName);
503	        String normalizedAddress = Households.normalize(address);
504	        boolean duplicate = this.clinicService.findAllOwners().stream()
505	            .anyMatch(existing ->
506	                Households.normalize(existing.getLastName()).equals(normalizedLastName)
507	                    && Households.normalize(existing.getAddress()).equals(normalizedAddress));
508	        if (duplicate) {
509	            throw new DuplicateHouseholdException(lastName, address);
510	        }
511	    }
512	
513	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
514	    @Override
515	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
516	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
517	        if (currentOwner == null) {
518	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
519	        }
520	        currentOwner.setAddress(ownerFieldsDto.getAddress());
521	        currentOwner.setCity(ownerFieldsDto.getCity());
522	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
523	        currentOwner.setLastName(ownerFieldsDto.getLastName());
524	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
525	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
526	        this.clinicService.saveOwner(currentOwner);
527	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
528	    }
529	
530	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
531	    @Transactional
532	    @Override
533	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
534	        Owner owner = this.clinicService.findOwnerById(ownerId);
535	        if (owner == null) {
536	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
537	        }
538	        this.clinicService.deleteOwner(owner);
539	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
540	    }
541	
542	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
543	    @Override
544	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
545	        Owner owner = this.clinicService.findOwnerById(ownerId);
546	        if (owner == null) {
547	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
548	        }
549	        HttpHeaders headers = new HttpHeaders();
550	        Pet pet = petMapper.toPet(petFieldsDto);
551	        owner.setId(ownerId);
552	        pet.setOwner(owner);
553	        pet.getType().setName(null);
554	        this.clinicService.savePet(pet);
555	        PetDto petDto = petMapper.toPetDto(pet);
556	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
557	            .buildAndExpand(pet.getId()).toUri());
558	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
559	    }
560	
561	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
562	    @Override
563	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
564	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
565	        if (currentOwner != null) {
566	            Pet currentPet = this.clinicService.findPetById(petId);
567	            if (currentPet != null) {
568	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
569	                currentPet.setName(petFieldsDto.getName());
570	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
571	                this.clinicService.savePet(currentPet);
572	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
573	            }
574	        }
575	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
576	    }
577	
578	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
579	    @Override
580	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
581	        HttpHeaders headers = new HttpHeaders();
582	        Visit visit = visitMapper.toVisit(visitFieldsDto);
583	        Pet pet = new Pet();
584	        pet.setId(petId);
585	        visit.setPet(pet);
586	        this.clinicService.saveVisit(visit);
587	        VisitDto visitDto = visitMapper.toVisitDto(visit);
588	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
589	            .buildAndExpand(visit.getId()).toUri());
590	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
591	    }
592	
593	
594	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
595	    @Override
596	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
597	        Owner owner = this.clinicService.findOwnerById(ownerId);
598	        if (owner != null) {
599	            Pet pet = owner.getPet(petId);
600	            if (pet != null) {
601	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
602	            }
603	        }
604	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
605	    }
606	}
