/**
 * Rejects creating an owner whose derived {@code identityKey} duplicates an existing owner's. All
 * duplicate detection is consolidated into this single key, built by
 * {@link Households#identityKey} from the owner's normalized telephone, normalized email (empty
 * when absent) and {@code householdId} (see {@link Households#householdId}). A create is rejected
 * only when the new owner's <em>whole</em> identity key equals an existing owner's, computed the
 * same way (existing telephones are re-normalized to E.164 and existing emails lower-cased so
 * equivalent values submitted in different formats still match).
 * <p>
 * Because the telephone is part of the key, two members of the same household (same
 * {@code householdId}) with different telephones have different keys and are both allowed; only an
 * exact full-key match is a duplicate.
 *
 * @param owner the owner being created, with its telephone and email already normalized
 * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity key
 */
private void rejectDuplicateIdentity(Owner owner) {
    String identityKey = identityKeyOf(owner.getTelephone(), owner.getEmail(),
        owner.getLastName(), owner.getAddress());
    boolean duplicate = this.clinicService.findAllOwners().stream()
        .anyMatch(existing -> identityKey.equals(identityKeyOf(
            toE164OrNull(existing.getTelephone()), existing.getEmail(),
            existing.getLastName(), existing.getAddress())));
    if (duplicate) {
        throw new DuplicateIdentityException(identityKey);
    }
}

/**
 * Builds the {@code identityKey} for the given owner fields, lower-casing the email (the form it is
 * stored in, see {@link #normalizeEmail}) so addresses differing only in letter case still match,
 * and deriving the {@code householdId} from the last name and address.
 */
private String identityKeyOf(String telephone, String email, String lastName, String address) {
    String normalizedEmail = email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
    String householdId = Households.householdId(lastName, address);
    return Households.identityKey(telephone, normalizedEmail, householdId);
}

